from itertools import groupby

sales = [("Pune", 300), ("Delhi", 500), ("Pune", 200),
         ("Delhi", 100), ("Agra", 50)]

def city_totals(rows):
    totals = {}
    ordered = sorted(rows, key=lambda r: r[0])
    for city, group in groupby(ordered, key=lambda r: r[0]):
        totals[city] = sum(amount for _, amount in group)
    return totals

print(city_totals(sales))

from collections import Counter

def top_words(text, k):
    words = (w.strip(".,!?").lower() for w in text.split())
    counts = Counter(w for w in words if w)
    return counts.most_common(k)

print(top_words("Chai, chai! Coffee? chai and coffee.", 2))

from collections import deque

def moving_average(times, k):
    window = deque(maxlen=k)
    averages = []
    for t in times:
        window.append(t)
        if len(window) == k:
            averages.append(round(sum(window) / k, 1))
    return averages

print(moving_average([120, 80, 100, 300, 90], 3))
